#!/usr/bin/env python3
"""Render a self-contained interactive HTML report from facts and analysis JSON.

Requires analysis schema_version 2.  Pass --live to enable live file reading
via serve_report.py (file text is not embedded; the browser fetches it on demand).
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path

DATA_MARKER = "const facts=__FACTS__,analysis=__ANALYSIS__,NS='http://www.w3.org/2000/svg';"


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("facts", type=Path)
    p.add_argument("analysis", type=Path)
    p.add_argument("--output", required=True, type=Path)
    p.add_argument("--live", action="store_true",
                   help="Enable live file reading via serve_report.py (omits embedded text)")
    return p.parse_args()


def safe_json(value: object) -> str:
    return (
        json.dumps(value, ensure_ascii=False)
        .replace("<", r"<")
        .replace(">", r">")
        .replace("&", r"&")
    )


def main() -> int:
    args = parse_args()
    facts = json.loads(args.facts.read_text(encoding="utf-8"))
    analysis = json.loads(args.analysis.read_text(encoding="utf-8"))

    if analysis.get("schema_version") != 2:
        raise SystemExit(
            f"error: render_report.py requires analysis schema_version 2, "
            f"got {analysis.get('schema_version')!r}"
        )
    if args.output.exists():
        raise SystemExit(f"error: output report already exists; choose a new path: {args.output}")
    if DATA_MARKER not in TEMPLATE:
        raise SystemExit("error: report template data marker is missing or ambiguous")

    if args.live:
        facts["live_preview"] = True
        for file_record in facts.get("files", []):
            if file_record.get("text") is not None:
                file_record["text"] = None
                if not file_record.get("skip_reason"):
                    file_record["skip_reason"] = "live preview requires the local server"

    data_assignment = (
        f"const facts={safe_json(facts)},"
        f"analysis={safe_json(analysis)},"
        f"NS='http://www.w3.org/2000/svg';"
    )
    rendered = TEMPLATE.replace(DATA_MARKER, data_assignment, 1)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(rendered, encoding="utf-8")
    print(json.dumps({
        "status": "ok",
        "output": str(args.output.resolve()),
        "bytes": args.output.stat().st_size,
        "live_preview": bool(args.live),
        "schema_version": analysis.get("schema_version"),
    }, ensure_ascii=False))
    return 0


